def signal(obs):
    # state for holding to amortize spread (100-120 steps)
    if 'hold' not in obs.state:
        obs.state['hold'] = {}
        obs.state['tgt'] = {}
    out = {}
    # trade only 0-fee venues A,C (strongest momentum), signal uses both listings
    bases = ['A', 'C']
    thresh = 1.4
    hold_calls = 10  # 10*10 =100 steps
    for base in bases:
        h = obs.state['hold'].get(base, 0)
        prev = obs.state['tgt'].get(base, 0.0)
        if h > 0:
            obs.state['hold'][base] = h - 1
            out[base] = prev
            continue
        m = obs.hist(base, 'mid', 80)
        mx = obs.hist(base + '.X', 'mid', 80)
        if m is None or mx is None or len(m) < 70 or len(mx) < 70:
            continue
        if m[-1] != m[-1] or mx[-1] != mx[-1] or m[-21] != m[-21] or mx[-21] != mx[-21]:
            continue
        bad = False
        for v in m[-30:]:
            if v != v:
                bad = True
                break
        for v in mx[-30:]:
            if v != v:
                bad = True
                break
        if bad:
            continue
        past = m[-1] - m[-21]
        pastx = mx[-1] - mx[-21]
        # estimate vol for each
        rets = []
        retsx = []
        for i in range(21, len(m)):
            if m[i] == m[i] and m[i-20] == m[i-20]:
                rets.append(m[i] - m[i-20])
            if mx[i] == mx[i] and mx[i-20] == mx[i-20]:
                retsx.append(mx[i] - mx[i-20])
        if len(rets) < 20 or len(retsx) < 20:
            continue
        mean = sum(rets)/len(rets)
        var = sum((x-mean)*(x-mean) for x in rets)/len(rets)
        std = math.sqrt(var) if var > 1e-9 else 10.0
        meanx = sum(retsx)/len(retsx)
        varx = sum((x-meanx)*(x-meanx) for x in retsx)/len(retsx)
        stdx = math.sqrt(varx) if varx > 1e-9 else 10.0
        if std < 1e-6 or stdx < 1e-6:
            continue
        z = past/std
        zx = pastx/stdx
        zavg = 0.5*(z+zx)
        if zavg > thresh:
            tgt = 1.0
        elif zavg < -thresh:
            tgt = -1.0
        else:
            tgt = 0.0
        if tgt != prev:
            obs.state['tgt'][base] = tgt
            obs.state['hold'][base] = hold_calls
            out[base] = tgt
        else:
            # keep same, no new hold needed
            out[base] = tgt
            obs.state['tgt'][base] = tgt
    return out

