def signal(obs):
    try:
        f = obs.last('IDX.F', 'mid')
        s = obs.last('IDX', 'mid')
        if f is None or s is None:
            return {}
        if f != f or s != s:
            return {}
        if f <= 0 or s <= 0:
            return {}
        b = f - s
        fh = obs.hist('IDX.F', 'mid', 200)
        sh = obs.hist('IDX', 'mid', 200)
        n = len(fh) if len(fh) < len(sh) else len(sh)
        tot = 0.0
        cnt = 0
        for i in range(n):
            a = fh[i]; c = sh[i]
            if a == a and c == c and a > 0 and c > 0:
                tot += (a - c)
                cnt += 1
        if cnt < 50:
            m = 35.0
        else:
            m = tot / cnt
        dev = b - m
        # fade deviation: rich basis -> short F / long IDX
        raw = -dev / 25.0
        if raw > 1.0:
            raw = 1.0
        elif raw < -1.0:
            raw = -1.0
        # deadzone to cut turnover
        if raw > -0.25 and raw < 0.25:
            raw = 0.0
        # quantize to reduce churn
        if raw >= 0:
            q = int(raw / 0.5 + 0.5) * 0.5
        else:
            q = int(raw / 0.5 - 0.5) * 0.5
        if q > 1.0:
            q = 1.0
        if q < -1.0:
            q = -1.0
        prev = obs.state.get('q', 0.0)
        if q == prev:
            return {}
        # hysteresis: ignore small wiggles
        d = q - prev
        if d < 0.4 and d > -0.4 and q != 0.0 and prev != 0.0:
            return {}
        obs.state['q'] = q
        if q == 0.0:
            return {'IDX.F': 0.0, 'IDX': 0.0}
        return {'IDX.F': float(-q), 'IDX': float(q)}
    except Exception:
        return {}

