def signal(obs):
    st = obs.state
    try:
        a = obs.last('A', 'mid')
        b = obs.last('B', 'mid')
        c = obs.last('C', 'mid')
        s = obs.last('IDX', 'mid')
    except Exception:
        return {}
    if a is None or b is None or c is None or s is None:
        return {}
    for v in (a, b, c, s):
        if not (v == v and v > 0):
            return {}
    bask = 0.3333 * a + 0.6667 * b + 0.1667 * c
    d = s - bask
    pos = st.get('pos', 0)
    ENTRY = 12.0
    EXIT = 4.0
    if pos == 0:
        if d > ENTRY:
            st['pos'] = -1
            return {'IDX': -1.0, 'A': 0.3333, 'B': 0.6667, 'C': 0.1667}
        if d < -ENTRY:
            st['pos'] = 1
            return {'IDX': 1.0, 'A': -0.3333, 'B': -0.6667, 'C': -0.1667}
        st['pos'] = 0
        return {'IDX': 0.0, 'A': 0.0, 'B': 0.0, 'C': 0.0}
    elif pos == -1:
        if d < EXIT:
            st['pos'] = 0
            return {'IDX': 0.0, 'A': 0.0, 'B': 0.0, 'C': 0.0}
        return {'IDX': -1.0, 'A': 0.3333, 'B': 0.6667, 'C': 0.1667}
    else:
        if d > -EXIT:
            st['pos'] = 0
            return {'IDX': 0.0, 'A': 0.0, 'B': 0.0, 'C': 0.0}
        return {'IDX': 1.0, 'A': -0.3333, 'B': -0.6667, 'C': -0.1667}

